changes.before:
/* order-status.css — customer order-status page (rides on custom-tees.css
   tokens: paper ground, ink greens, Bricolage display type). */

.status-body { padding-bottom: 0; }

.status-main {
    max-width: 680px; margin: 0 auto; padding: 40px 18px 60px;
}

.status-card {
    background: var(--card); border: 1px solid var(--line); border-radius: 16px;
    box-shadow: var(--shadow-card); padding: 34px 28px; text-align: center;
}
.status-card h1 { font-size: 26px; font-weight: 800; margin-bottom: 6px; }
.status-card > p { color: var(--ink-soft); }

.status-kicker {
    text-transform: uppercase; letter-spacing: 0.14em; font-size: 12px;
    font-weight: 700; color: var(--green-700); margin-bottom: 4px;
}
.status-style { font-size: 15px; color: var(--ink-soft); }

.status-style .status-rush {
    display: inline-block; margin-left: 6px; padding: 2px 10px;
    background: var(--rush-soft); color: var(--rush-deep);
    border: 1px solid var(--rush); border-radius: 999px;
    font-size: 12px; font-weight: 700;
}

.status-style .status-date {
    display: block; font-size: 12.5px; color: var(--ink-faint); margin-top: 2px;
}

.status-spin { font-size: 34px; color: var(--green-700); margin-bottom: 14px; }
.status-check { font-size: 46px; color: var(--green-700); margin-bottom: 14px; }
.status-check.is-amber { color: var(--warn); }
.status-phone a { font-weight: 700; }

.status-promise {
    display: inline-block; background: var(--green-50); color: var(--green-900);
    border: 1px dashed var(--green-700); border-radius: 999px; padding: 8px 18px;
    font-weight: 600; font-size: 14.5px; margin: 10px 0 4px;
}
.status-promise strong { font-family: var(--font-display); }

.status-tracking { margin: 14px 0 4px; }
.status-tracking .btn { text-decoration: none; }

/* ── Timeline (4 steps) ──────────────────────────────────────────── */
.status-timeline {
    text-align: left; max-width: 460px; margin: 26px auto 6px;
    display: grid; gap: 0; position: relative;
}

.status-step {
    display: flex; gap: 14px; align-items: flex-start; position: relative;
    padding-bottom: 22px;
}
.status-step:last-child { padding-bottom: 0; }

/* connector line */
.status-step:not(:last-child)::before {
    content: ''; position: absolute; left: 15px; top: 32px; bottom: 0;
    width: 2px; background: var(--line-strong);
}
.status-step.is-done:not(:last-child)::before { background: var(--green-700); }

.status-step-dot {
    flex: none; width: 32px; height: 32px; border-radius: 50%;
    display: inline-flex; align-items: center; justify-content: center;
    font-size: 13px; border: 2px solid var(--line-strong);
    background: var(--card); color: var(--ink-faint); z-index: 1;
}

.status-step.is-done .status-step-dot {
    background: var(--green-700); border-color: var(--green-700); color: var(--color-on-brand);
}

.status-step.is-current .status-step-dot {
    background: var(--green-50); border-color: var(--green-700);
    box-shadow: 0 0 0 4px var(--green-100);
}
.status-step-body strong { display: block; font-size: 15px; }
.status-step.is-pending .status-step-body strong { color: var(--ink-faint); }
.status-step.is-current .status-step-body strong { color: var(--green-900); }
.status-step-body small { color: var(--ink-faint); font-size: 12.5px; }

/* ── Pickup card ─────────────────────────────────────────────────── */
.status-pickup {
    display: flex; gap: 14px; align-items: flex-start; text-align: left;
    max-width: 460px; margin: 18px auto 0;
    background: var(--paper-deep); border: 1px solid var(--line);
    border-radius: var(--radius); padding: 14px 16px;
}
.status-pickup i { color: var(--green-700); font-size: 20px; margin-top: 3px; }
.status-pickup strong { display: block; font-size: 14.5px; }
.status-pickup span { font-size: 13px; color: var(--ink-soft); }

/* ── Mockups ─────────────────────────────────────────────────────── */
.status-mockups { display: flex; gap: 12px; flex-wrap: wrap; justify-content: center; margin: 18px 0 4px; }
.status-mockups figure { margin: 0; width: 110px; }
.status-mockups img { width: 100%; border-radius: 10px; border: 1px solid var(--line); background: var(--paper-deep); }
.status-mockups figcaption { font-size: 11px; color: var(--ink-faint); margin-top: 3px; }

/* ── Order summary ───────────────────────────────────────────────── */
.status-h2 {
    font-size: 17px; margin-top: 26px; padding-top: 18px;
    border-top: 1px solid var(--line);
}
.status-table-wrap { max-width: 460px; margin: 12px auto 0; overflow-x: auto; }
.status-table { width: 100%; border-collapse: collapse; font-size: 14px; }

.status-table th {
    text-align: left; font-size: 11.5px; text-transform: uppercase;
    letter-spacing: 0.06em; color: var(--ink-faint);
    border-bottom: 1px solid var(--line-strong); padding: 4px 8px 6px;
}
.status-table td { padding: 6px 8px; border-bottom: 1px solid var(--line); }
.status-table th:nth-child(n+3), .status-table td:nth-child(n+3) { text-align: right; }

.status-summary { text-align: left; margin: 14px auto 0; max-width: 460px; }
.status-summary .tot-row { display: flex; justify-content: space-between; font-size: 14px; padding: 3px 8px; }

.status-summary .tot-row.is-grand {
    font-family: var(--font-display); font-weight: 800; font-size: 18px;
    border-top: 2px solid var(--ink); padding-top: 8px; margin-top: 6px;
}

.status-questions { margin-top: 22px; font-size: 13.5px; color: var(--ink-soft); }

@media (width <= 560px) {
    .status-card { padding: 26px 16px; }
    .status-card h1 { font-size: 22px; }
}

/* 2026-09-05 review: the hidden attribute must beat any display rule */
/* stylelint-disable-next-line declaration-no-important -- the hidden attribute must beat any display rule */
[hidden] { display: none !important; }

