/* stylelint-disable no-duplicate-selectors -- legacy sheet: rules were appended over time; merging them would reorder the cascade (2026-09-07) */

/* vendor-portal.css — L&P Screen Printing subcontractor job portal (/vendor).
   Self-contained (vendor-facing page — deliberately does NOT pull staff dashboard CSS).
   NWCA brand greens match the customer portal. */

/* Page theme (CSS standardization, 2026-09-07): this page's own colours, auto-named by hue, merged into its
   existing :root. Map them to shared_components/css/tokens.css names when the page is redesigned;
   raw hex is allowed ONLY in this block. */
/* stylelint-disable color-no-hex */
:root {
    --vendor-portal-indigo: #5b21b6;
    --vendor-portal-cyan: #93c5fd;
  --vp-green-dark: var(--brand-800);
  --vp-green: var(--brand-mid);
  --vp-green-pale: var(--brand-100);
  --vp-ink: var(--gray-800);
  --vp-muted: var(--gray-500);
  --vp-border: var(--gray-200);
  --vp-bg: var(--gray-100);
  --vp-card: var(--color-surface);
  --vp-rush: var(--red-600);
  --vp-radius: 10px;
  --vp-shadow: 0 1px 3px rgb(0 0 0 / 8%);
}
/* stylelint-enable color-no-hex */

* { box-sizing: border-box; }

/* `hidden` must beat every display rule below (.vp-error is display:flex, .vp-btn inline-flex) -
   without this the red error banner was visible on EVERY load (found 2026-09-05). */
/* stylelint-disable-next-line declaration-no-important -- the hidden attribute must beat any display rule */
[hidden] { display: none !important; }

body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background: var(--vp-bg);
  color: var(--vp-ink);
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

/* ── Header ─────────────────────────────────────────────── */
.vp-header {
  background: var(--vp-card);
  border-bottom: 3px solid var(--vp-green-dark);
  box-shadow: var(--vp-shadow);
}

.vp-header-inner {
  max-width: 1200px;
  margin: 0 auto;
  padding: 12px 20px;
  display: flex;
  align-items: center;
  gap: 16px;
  flex-wrap: wrap;
}
.vp-logo { height: 44px; width: auto; }
.vp-header-title { flex: 1; min-width: 200px; }
.vp-header-title h1 { margin: 0; font-size: 1.15rem; color: var(--vp-green-dark); }
.vp-header-sub { font-size: 0.8rem; color: var(--vp-muted); }
.vp-header-user { display: flex; align-items: center; gap: 10px; }

.vp-user-chip {
  font-size: 0.8rem;
  color: var(--vp-muted);
  background: var(--vp-green-pale);
  padding: 5px 10px;
  border-radius: 999px;
}

/* ── Layout ─────────────────────────────────────────────── */
.vp-container {
  max-width: 1200px;
  width: 100%;
  margin: 0 auto;
  padding: 20px;
  flex: 1;
}

.vp-footer {
  text-align: center;
  padding: 18px;
  font-size: 0.8rem;
  color: var(--vp-muted);
}

/* ── Buttons / chips ───────────────────────────────────── */
.vp-btn {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  border: 1px solid var(--vp-border);
  background: var(--vp-card);
  color: var(--vp-ink);
  border-radius: 8px;
  padding: 8px 14px;
  font-size: 0.85rem;
  cursor: pointer;
  text-decoration: none;
  transition: background 0.15s, color 0.15s;
}
.vp-btn--primary { background: var(--vp-green); border-color: var(--vp-green); color: var(--color-on-brand); }
.vp-btn--primary:hover { background: var(--vp-green-dark); }
