.vp-job-id { font-size: 0.75rem; color: var(--vp-muted); font-family: ui-monospace, Menlo, Consolas, monospace; }

.vp-job-company {
  font-weight: 600;
  margin: 2px 0 4px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.vp-job-meta { font-size: 0.78rem; color: var(--vp-muted); display: flex; gap: 10px; flex-wrap: wrap; }
.vp-job-badges { margin-top: 7px; display: flex; gap: 6px; flex-wrap: wrap; }

.vp-badge {
  display: inline-block;
  font-size: 0.7rem;
  font-weight: 600;
  border-radius: 999px;
  padding: 2px 9px;
