}
.vp-badge--rush { background: var(--red-100); color: var(--vp-rush); }
.vp-badge--status-Requested { background: var(--amber-100); color: var(--amber-800); }
.vp-badge--status-Ordered { background: var(--sky-100); color: var(--blue-800); }
.vp-badge--status-PO_Created { background: var(--color-ruth-tint); color: var(--vendor-portal-indigo); }
.vp-badge--status-Shipped { background: var(--emerald-100); color: var(--emerald-800); }
.vp-badge--status-Received { background: var(--vp-green-pale); color: var(--vp-green-dark); }
.vp-badge--status-Cancelled { background: var(--gray-100); color: var(--vp-muted); }
