.vp-meta {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(170px, 1fr));
  gap: 12px 18px;
  margin: 0;
}
.vp-meta dt { font-size: 0.7rem; text-transform: uppercase; letter-spacing: 0.04em; color: var(--vp-muted); }
.vp-meta dd { margin: 2px 0 0; font-size: 0.9rem; font-weight: 500; overflow-wrap: anywhere; }

