  font-weight: 600;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.vp-file-meta { font-size: 0.72rem; color: var(--vp-muted); display: flex; gap: 8px; flex-wrap: wrap; }

.vp-file-type {
  font-size: 0.65rem;
  font-weight: 700;
  text-transform: uppercase;
  background: var(--vp-green-pale);
  color: var(--vp-green-dark);
  border-radius: 4px;
  padding: 1px 6px;
}
.vp-file-type--mockup { background: var(--sky-100); color: var(--blue-800); }

/* Mockup panel */
.vp-mockup-img {
  width: 100%;
  max-height: 420px;
  object-fit: contain;
  border-radius: 8px;
  background: var(--vp-green-pale);
}

/* Timeline */
.vp-comment-form { display: flex; gap: 8px; margin-bottom: 14px; align-items: flex-end; }

.vp-comment-form textarea {
  flex: 1;
  border: 1px solid var(--vp-border);
  border-radius: 8px;
  padding: 8px 10px;
  font-size: 0.85rem;
  font-family: inherit;
  resize: vertical;
}
.vp-timeline { display: flex; flex-direction: column; gap: 12px; max-height: 460px; overflow-y: auto; }
.vp-note { border-left: 3px solid var(--vp-green-pale); padding: 2px 0 2px 12px; }
.vp-note--vendor { border-left-color: var(--vp-green); }
.vp-note--status { border-left-color: var(--vendor-portal-cyan); }
.vp-note-head { font-size: 0.72rem; color: var(--vp-muted); margin-bottom: 2px; }
.vp-note-head strong { color: var(--vp-ink); }
.vp-note-text { font-size: 0.85rem; white-space: pre-wrap; overflow-wrap: anywhere; }

/* ── 2026-09-05 review ─────────────────────────────────────── */
.vp-sr { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0; }
.vp-btn--sm { padding: 5px 10px; font-size: 0.78rem; }
.vp-error { flex-wrap: wrap; }
.vp-error #vp-error-retry { margin-left: auto; }
.vp-chip-count { font-size: 0.72rem; opacity: 0.8; margin-left: 2px; }
.vp-chip-count:empty { display: none; }

.vp-chip:focus-visible, .vp-btn:focus-visible, .vp-job-card:focus-visible, .vp-search input:focus-visible,
.vp-comment-form textarea:focus-visible, .vp-detail-company:focus-visible { outline: 3px solid var(--vp-green); outline-offset: 2px; }
.vp-detail-company:focus { outline: none; }
/* stylelint-disable-next-line declaration-no-important -- legacy: outranks a higher-specificity rule — re-examine when this page is redesigned */
.vp-overdue { color: var(--vp-rush) !important; font-weight: 600; }
.vp-job-card--pastdue { border-left: 4px solid var(--vp-rush); }
.vp-comment-hint { font-size: 0.72rem; color: var(--vp-muted); margin: -8px 0 12px; }
.vp-comment-status { font-size: 0.8rem; color: var(--vp-green-dark); background: var(--vp-green-pale); border-radius: 6px; padding: 6px 10px; margin-bottom: 12px; }
.vp-mockup-img { display: block; }

@media (width <= 560px) {
  .vp-header-inner { padding: 10px 14px; gap: 10px; }
  .vp-logo { height: 36px; }
  .vp-header-title h1 { font-size: 1rem; }
  .vp-header-sub { display: none; }
  .vp-header-user { width: 100%; justify-content: space-between; }
  .vp-container { padding: 14px; }
  .vp-search { flex: 1 1 100%; min-width: 0; }
  .vp-job-grid { grid-template-columns: 1fr; }
  .vp-detail-header { padding: 14px; }
  .vp-card-body { padding: 12px; }
  .vp-comment-form { flex-direction: column; align-items: stretch; }
  .vp-timeline { max-height: none; }
}

